+class DisiplinCard extends StatefulWidget {
+  final String santriId;
+
+  const DisiplinCard({super.key, required this.santriId});
+
+  @override
+  State<DisiplinCard> createState() => _DisiplinCardState();
+}
+
+class _DisiplinCardState extends State<DisiplinCard> {
+  List<KehadiranPeriode>? kehadiranPeriode;
+  List<KehadiranTahunan>? kehadiranTahunan;
+  bool isLoading = true;
+  String selectedPeriode = 'seminggu';
+
+  final List<Map<String, String>> filterOptions = [
+    {'value': 'seminggu', 'label': '7 Hari'},
+    {'value': 'sebulan', 'label': '1 Bulan'},
+    {'value': 'setahun', 'label': '1 Tahun'},
+  ];
+
+  @override
+  void initState() {
+    super.initState();
+    _loadKehadiranData();
+  }
+
+  @override
+  void didUpdateWidget(covariant DisiplinCard oldWidget) {
+    super.didUpdateWidget(oldWidget);
+    if (oldWidget.santriId != widget.santriId) {
+      _loadKehadiranData();
+    }
+  }
+
+  Future<void> _loadKehadiranData() async {
+    setState(() => isLoading = true);
+
+    try {
+      if (selectedPeriode == 'setahun') {
+        final response = await ApiService.getKehadiranTahunan(widget.santriId);
+        if (response.success && response.data != null) {
+          setState(() {
+            kehadiranTahunan = response.data;
+            kehadiranPeriode = null;
+            isLoading = false;
+          });
+        } else {
+          setState(() => isLoading = false);
+          if (mounted) {
+            ScaffoldMessenger.of(context).showSnackBar(
+              SnackBar(content: Text(response.message)),
+            );
+          }
+        }
+      } else {
+        final response = await ApiService.getKehadiranPeriode(
+          widget.santriId, 
+          selectedPeriode,
+        );
+        if (response.success && response.data != null) {
+          setState(() {
+            kehadiranPeriode = response.data;
+            kehadiranTahunan = null;
+            isLoading = false;
+          });
+        } else {
+          setState(() => isLoading = false);
+          if (mounted) {
+            ScaffoldMessenger.of(context).showSnackBar(
+              SnackBar(content: Text(response.message)),
+            );
+          }
+        }
+      }
+    } catch (e) {
+      setState(() => isLoading = false);
+      if (mounted) {
+        ScaffoldMessenger.of(context).showSnackBar(
+          SnackBar(content: Text('Error loading data: $e')),
+        );
+      }
+    }
+  }
+
+  Map<String, dynamic> _getIbadahSummary() {
+    if ((selectedPeriode != 'setahun' && kehadiranPeriode == null) || 
