+            kehadiranTahunan!.isNotEmpty)) {
+      if (selectedPeriode == 'setahun') {
+        // Hitung untuk data tahunan (per bulan)
+        for (var bulan in kehadiranTahunan!) {
+          totalSholat += bulan.totalKehadiran;
+          totalSeharusnya += 30 * 5; // Asumsi 30 hari per bulan
+        }
+      } else {
+        // Hitung untuk data harian
+        for (var harian in kehadiranPeriode!) {
+          totalSholat += harian.jumlahKehadiran;
+          totalSeharusnya += 5; // 5 kali sholat per hari
+        }
+      }
+
+      persentase =
